css:
.card {
  background-color: #25241c;
  border: 3px solid #f7df1e;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  font-weight: 700;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  padding: 30px 40px;
  color: #f7df1e;
  border-radius: 45px;
}

.App-logo {
  pointer-events: none;
  width: 120px;
  margin-bottom: 20px;
}

.App-button {
  padding: 10px 20px;
  background-color: transparent;
  color: #f7df1e;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  font-size: 15px;
  border: 3px solid #f7df1e;
  border-radius: 5em;
  margin-top: 20px;
  transition: 0.2s;
}

.App-button:hover {
  color: #2e2d23;
  background-color: #f7df1e;
}
